import argparse
from operations import Calculator

def main():
    """CLI entry point for the calculator."""
    parser = argparse.ArgumentParser(description="CLI Calculator")

    # Adding operation choice and two positional float arguments
    parser.add_argument("op", choices=['add', 'sub', 'mul', 'div'], help="Operation to perform")
    parser.add_argument("a", type=float, help="First operand")
    parser.add_argument("b", type=float, help="Second operand")

    args = parser.parse_args()
    calc = Calculator()

    try:
        # Perform calculation
        if args.op == 'add':
            result = calc.add(args.a, args.b)
        elif args.op == 'sub':
            result = calc.subtract(args.a, args.b)
        elif args.op == 'mul':
            result = calc.multiply(args.a, args.b)
        elif args.op == 'div':
            result = calc.divide(args.a, args.b)

        print(f"Result: {result}")

        # Display history
        print("Calculation History:")
        for entry in calc.get_history():
            print(f" - {entry}")

    except ValueError as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

